export default async function install(app){const search=document.getElementById('app-widget-place-search');const auto=search?.shadowRoot?.querySelector('calcite-autocomplete');const input=auto?.shadowRoot?.querySelector('calcite-input');app.assert(input?.shadowRoot,'Search input is not ready');const previous=search.allPlaceholder;const originals=new Map();const update=()=>{for(const icon of input.shadowRoot.querySelectorAll('calcite-icon')){if(icon.icon!=='search')continue;if(!originals.has(icon))originals.set(icon,icon.scale);if(icon.scale!=='m')icon.scale='m';}};const observer=new MutationObserver(update);app.onCleanup(()=>{observer.disconnect();search.allPlaceholder=previous;for(const [icon,scale] of originals)icon.scale=scale;});search.allPlaceholder='Zoek een plek of adres';update();observer.observe(input.shadowRoot,{subtree:true,childList:true,attributes:true,attributeFilter:['scale']});await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const icon=[...input.shadowRoot.querySelectorAll('calcite-icon')].find(e=>e.icon==='search');const field=input.shadowRoot.querySelector('input');const r=icon.getBoundingClientRect();return {placeholder:field.placeholder,searchIconScale:icon.scale,searchIconWidth:r.width,searchIconHeight:r.height,shadow:getComputedStyle(search).boxShadow};}